using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_9500_cents_on_a_10000_cent_basket()
    {
        // Returning customer in the Bronze tier is charged 9500 cents on a 10000 cent basket
        var query = new CalculateLoyaltyDiscountQuery(SubtotalCents: 10000, LoyaltyTier: LoyaltyTier.Bronze);

        var quote = new CalculateLoyaltyDiscount().Handle(query);

        Assert.Equal(9500, quote.TotalCents);
    }
}
